app/page.tsx<pre><code>import Link from "next/link";

export default function Home() {
  return (
    &lt;main&gt;
      &lt;h1&gt;Home&lt;/h1&gt;
      &lt;ul&gt;
        &lt;li&gt;&lt;Link href="/about"&gt;About&lt;/Link&gt;&lt;/li&gt;
        &lt;li&gt;&lt;Link href="/blog/routing"&gt;A blog post&lt;/Link&gt;&lt;/li&gt;
        &lt;li&gt;&lt;Link href={{ pathname: "/search", query: { q: "layouts" } }}&gt;Search for layouts&lt;/Link&gt;&lt;/li&gt;
        &lt;li&gt;&lt;Link href="/about#team"&gt;Jump to the team section&lt;/Link&gt;&lt;/li&gt;
      &lt;/ul&gt;
    &lt;/main&gt;
  );
}
</code></pre> <p><code>&lt;Link&gt;</code> renders a real <code>&lt;a&gt;</code> element, so it is crawlable, works with middle-click and "open in new tab", and degrades gracefully if JavaScript fails. Any extra props (<code>className</code>, <code>aria-current</code>, <code>target</code>) pass through to the <code>&lt;a&gt;</code>.</p> <p>Useful props:</p> Prop Effect <code>href</code> Path string or URL object. Required. <code>replace</code> Replace the current history entry instead of pushing a new one. <code>scroll</code> Set <code>false</code> to keep the scroll position after navigation. <code>prefetch</code> <code>"auto"</code>/<code>null</code> (default), <code>true</code>, or <code>false</code> — see below. <p>For links to other sites, use a normal <code>&lt;a&gt;</code>; <code>&lt;Link&gt;</code> is for routes in your app.</p>

app/blog/PostCard.module.css<pre><code>.card { display: grid; gap: 0.25rem; padding: 1rem; border-radius: 10px; }
.card:focus-within { outline: 2px solid var(--accent); outline-offset: 2px; }
.meta { font-size: 0.875rem; opacity: 0.75; }
.link { text-decoration: none; font-weight: 600; }
.link::after { content: ""; position: absolute; inset: 0; } /* whole card clickable */
.wrapper { position: relative; }
</code></pre> app/blog/PostCard.tsx<pre><code>import Link from "next/link";
import styles from "./PostCard.module.css";

export function PostCard({ slug, title, date }: { slug: string; title: string; date: string }) {
  return (
    &lt;div className={`${styles.wrapper} ${styles.card}`}&gt;
      &lt;Link className={styles.link} href={`/blog/${slug}`}&gt;{title}&lt;/Link&gt;
      &lt;time className={styles.meta} dateTime={date}&gt;
        {new Date(date).toLocaleDateString("en-GB", { dateStyle: "medium" })}
      &lt;/time&gt;
    &lt;/div&gt;
  );
}
</code></pre> <p>The card is a Server Component, makes the whole area clickable with a pseudo-element instead of wrapping block content in a link, and shows a focus ring for keyboard users.</p>

app/page.tsx<pre><code>import Image from "next/image";
import hero from "./hero.jpg"; // static import: width, height and blur data are known at build time

export default function Home() {
  return (
    &lt;main&gt;
      &lt;Image
        src={hero}
        alt="A developer's desk with a laptop showing a code editor"
        placeholder="blur"
        fetchPriority="high"      // the hero is the Largest Contentful Paint element
        sizes="100vw"
        style={{ width: "100%", height: "auto" }}
      /&gt;
      &lt;Image src="/team/ana.png" alt="Ana, course author" width={160} height={160} /&gt;
    &lt;/main&gt;
  );
}
</code></pre> <p>What <code>&lt;Image&gt;</code> does for you:</p> <ul> <li>Prevents layout shift — it always reserves space, either from the static import's   dimensions or from the <code>width</code>/<code>height</code> you give it.</li> <li>Serves modern formats at the right size — requests go through the image optimiser   (<code>/_next/image?url=…&amp;w=…&amp;q=…</code>), which resizes and re-encodes on demand and caches the   result.</li> <li>Emits a responsive <code>srcset</code> — combined with <code>sizes</code>, the browser downloads only   the resolution it needs.</li> <li>Lazy-loads by default — images below the fold load as they approach the viewport.</li> </ul> <p>For your above-the-fold hero, tell the browser it matters: <code>fetchPriority="high"</code> or <code>loading="eager"</code>. (In Next.js 16 the old <code>priority</code> prop is deprecated in favour of <code>preload</code>, and the docs recommend <code>loading="eager"</code> or <code>fetchPriority="high"</code> in most cases.)</p>

app/layout.tsx<pre><code>import { Inter, JetBrains_Mono } from "next/font/google";
import "./globals.css";

const inter = Inter({ subsets: ["latin"], display: "swap", variable: "--font-sans" });
const mono = JetBrains_Mono({ subsets: ["latin"], variable: "--font-mono" });

export default function RootLayout({ children }: LayoutProps&lt;"/"&gt;) {
  return (
    &lt;html lang="en" className={`${inter.variable} ${mono.variable}`}&gt;
      &lt;body&gt;{children}&lt;/body&gt;
    &lt;/html&gt;
  );
}
</code></pre> app/globals.css<pre><code>body { font-family: var(--font-sans), system-ui, sans-serif; }
code, pre { font-family: var(--font-mono), ui-monospace, monospace; }
</code></pre> <p><code>next/font/google</code> downloads the font files at build time and serves them from your own domain — the browser never contacts Google, which is better for privacy and removes a DNS lookup and connection. When we built a test app with <code>Inter</code>, the rendered HTML referenced a file under <code>/_next/static/media/…woff2</code> on the app's own origin.</p> <p>For fonts you own, use <code>next/font/local</code>:</p> <pre><code>import localFont from "next/font/local";
const brand = localFont({ src: "./fonts/Brand-Variable.woff2", variable: "--font-brand" });
</code></pre>

app/users/page.tsx<pre><code>type User = { id: number; name: string; email: string };

export default async function UsersPage() {
  const res = await fetch("https://jsonplaceholder.typicode.com/users");
  if (!res.ok) throw new Error(`Failed to load users: ${res.status}`);
  const users: User[] = await res.json();

  return (
    &lt;main&gt;
      &lt;h1&gt;Users&lt;/h1&gt;
      &lt;ul&gt;
        {users.map((u) =&gt; (
          &lt;li key={u.id}&gt;
            {u.name} — &lt;a href={`mailto:${u.email}`}&gt;{u.email}&lt;/a&gt;
          &lt;/li&gt;
        ))}
      &lt;/ul&gt;
    &lt;/main&gt;
  );
}
</code></pre> <p>(<code>jsonplaceholder.typicode.com</code> is a free public test API; any JSON endpoint works.)</p> <p>Because this runs on the server:</p> <ul> <li>You can call any data source — a database client, the file system, an internal   service on a private network — not just HTTP.</li> <li>Secrets used in the call (API keys, DB passwords) never reach the browser.</li> <li>Throwing an error is caught by the nearest <code>error.tsx</code> (Level 2 · 02).</li> </ul> <p>Reading local files is just as direct:</p> app/changelog/page.tsx<pre><code>import { readFile } from "node:fs/promises";
import path from "node:path";

export default async function Changelog() {
  const text = await readFile(path.join(process.cwd(), "CHANGELOG.md"), "utf8");
  return &lt;pre&gt;{text}&lt;/pre&gt;;
}
</code></pre>

app/oss/page.tsx<pre><code>import { getRepos } from "@/lib/github";

export const metadata = { title: "Open source" };

export default async function OpenSource() {
  const [vercel, facebook] = await Promise.all([getRepos("vercel"), getRepos("facebook")]);
  return (
    &lt;main&gt;
      &lt;h1&gt;Recently updated repositories&lt;/h1&gt;
      &lt;div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "2rem" }}&gt;
        {[{ org: "vercel", repos: vercel }, { org: "facebook", repos: facebook }].map(({ org, repos }) =&gt; (
          &lt;section key={org}&gt;
            &lt;h2&gt;{org}&lt;/h2&gt;
            &lt;ol&gt;
              {repos.map((r) =&gt; (
                &lt;li key={r.name}&gt;
                  &lt;a href={r.html_url}&gt;{r.name}&lt;/a&gt; ★ {r.stargazers_count}
                &lt;/li&gt;
              ))}
            &lt;/ol&gt;
          &lt;/section&gt;
        ))}
      &lt;/div&gt;
    &lt;/main&gt;
  );
}
</code></pre> <p>Build it and the route shows as <code>○</code> — the repositories were fetched during the build. Add <code>await connection()</code> at the top and it becomes <code>ƒ</code>. The GitHub API is rate-limited for unauthenticated requests, which is itself a good argument for not fetching on every request unless you need to.</p>

lib/blog.ts<pre><code>import "server-only";
import { readdir, readFile } from "node:fs/promises";
import path from "node:path";
import { cache } from "react";
import { marked } from "marked";

const POSTS_DIR = path.join(process.cwd(), "content", "posts");

export type PostMeta = { slug: string; title: string; date: string; summary: string };
export type Post = PostMeta &amp; { html: string };

function parseFrontMatter(source: string): { data: Record&lt;string, string&gt;; body: string } {
  const match = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/.exec(source);
  if (!match) return { data: {}, body: source };
  const data: Record&lt;string, string&gt; = {};
  for (const line of match[1].split(/\r?\n/)) {
    const i = line.indexOf(":");
    if (i &gt; 0) data[line.slice(0, i).trim()] = line.slice(i + 1).trim();
  }
  return { data, body: source.slice(match[0].length) };
}

function toMeta(slug: string, data: Record&lt;string, string&gt;): PostMeta {
  if (!data.title || !data.date) throw new Error(`Post "${slug}" needs title and date`);
  return { slug, title: data.title, date: data.date, summary: data.summary ?? "" };
}

export const getAllPosts = cache(async (): Promise&lt;PostMeta[]&gt; =&gt; {
  const files = (await readdir(POSTS_DIR)).filter((f) =&gt; f.endsWith(".md"));
  const posts = await Promise.all(
    files.map(async (file) =&gt; {
      const slug = file.replace(/\.md$/, "");
      const { data } = parseFrontMatter(await readFile(path.join(POSTS_DIR, file), "utf8"));
      return toMeta(slug, data);
    }),
  );
  return posts.sort((a, b) =&gt; b.date.localeCompare(a.date));
});

export const getPost = cache(async (slug: string): Promise&lt;Post | null&gt; =&gt; {
  if (!/^[a-z0-9-]+$/.test(slug)) return null; // never let a URL segment walk the file system
  try {
    const source = await readFile(path.join(POSTS_DIR, `${slug}.md`), "utf8");
    const { data, body } = parseFrontMatter(source);
    return { ...toMeta(slug, data), html: await marked.parse(body) };
  } catch {
    return null;
  }
});
</code></pre> <p>Design notes:</p> <ul> <li>The front-matter parser is deliberately tiny (key: value lines). For nested YAML   you'd use a library such as <code>gray-matter</code>; the point here is that there's no magic.</li> <li>A post missing <code>title</code> or <code>date</code> throws, which fails the build. That's what you   want: broken content should never deploy silently.</li> <li>The slug regex matters. Without it, a request for <code>/posts/..%2F..%2Fetc%2Fpasswd</code>   would be joined into a file path. Validating input from the URL is a habit worth   forming now.</li> <li><code>cache()</code> lets the index, the page and <code>generateMetadata</code> share results within one   render.</li> </ul>

app/posts/page.tsx<pre><code>import Link from "next/link";
import { getAllPosts } from "@/lib/blog";

export const metadata = { title: "Posts" };

