        {posts.map((p) =&gt; (
          &lt;li key={p.slug}&gt;
            &lt;Link href={`/posts/${p.slug}`}&gt;{p.title}&lt;/Link&gt;{" "}
            &lt;time dateTime={p.date}&gt;{p.date}&lt;/time&gt;
