app/posts/[slug]/page.tsx<pre><code>import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { getAllPosts, getPost } from "@/lib/blog";

export const dynamicParams = false; // only slugs from generateStaticParams exist

export async function generateStaticParams() {
  return (await getAllPosts()).map((p) =&gt; ({ slug: p.slug }));
}

export async function generateMetadata({ params }: PageProps&lt;"/posts/[slug]"&gt;): Promise&lt;Metadata&gt; {
  const { slug } = await params;
  const post = await getPost(slug);
  if (!post) return {};
  return { title: post.title, description: post.summary, openGraph: { type: "article", publishedTime: post.date } };
}

export default async function PostPage({ params }: PageProps&lt;"/posts/[slug]"&gt;) {
  const { slug } = await params;
  const post = await getPost(slug);
  if (!post) notFound();
  return (
    &lt;article&gt;
      &lt;p&gt;&lt;Link href="/posts"&gt;← All posts&lt;/Link&gt;&lt;/p&gt;
      &lt;h1&gt;{post.title}&lt;/h1&gt;
      &lt;time dateTime={post.date}&gt;{post.date}&lt;/time&gt;
      &lt;div dangerouslySetInnerHTML={{ __html: post.html }} /&gt;
    &lt;/article&gt;
  );
}
</code></pre> <p>The folder name <code>[slug]</code> makes this a dynamic segment: one file handles every post. <code>generateStaticParams</code> lists the slugs to prerender, and <code>dynamicParams = false</code> says "any other slug is a 404" rather than "try to render it on demand". Level 2 lesson 01 covers these in depth.</p> <p><code>dangerouslySetInnerHTML</code> and trust</p> <p>Rendering HTML from Markdown is safe here because you write the Markdown and it's in your repository. If posts ever come from users, sanitise the HTML (for example with DOMPurify on the server) — <code>marked</code> does not sanitise by default.</p>

app/docs/[...path]/page.tsx<pre><code>import { notFound } from "next/navigation";
import { getDoc } from "@/lib/docs";

export default async function DocPage({ params }: PageProps&lt;"/docs/[...path]"&gt;) {
  const { path } = await params;              // e.g. ["guides", "install"]
  const doc = await getDoc(path.join("/"));   // "guides/install"
  if (!doc) notFound();

  return (
    &lt;article&gt;
      &lt;nav aria-label="Breadcrumb"&gt;
        {path.map((part, i) =&gt; (
          &lt;span key={i}&gt; / {decodeURIComponent(part)}&lt;/span&gt;
        ))}
      &lt;/nav&gt;
      &lt;h1&gt;{doc.title}&lt;/h1&gt;
      &lt;div dangerouslySetInnerHTML={{ __html: doc.html }} /&gt;
    &lt;/article&gt;
  );
}
</code></pre> <p>Segments arrive URL-encoded for characters such as spaces; decode for display, and validate before using them in a file path or query.</p>

lib/products.ts<pre><code>import "server-only";

export type Product = { id: number; name: string; price: number; category: string };

const PRODUCTS: Product[] = [
  { id: 1, name: "Ceramic mug", price: 12, category: "kitchen" },
  { id: 2, name: "Linen apron", price: 28, category: "kitchen" },
  { id: 3, name: "Desk lamp", price: 45, category: "office" },
];

export async function listProductIds() {
  return PRODUCTS.map((p) =&gt; p.id);
}
export async function getProduct(id: number) {
  return PRODUCTS.find((p) =&gt; p.id === id) ?? null;
}
export async function listByCategory(category: string) {
  return PRODUCTS.filter((p) =&gt; p.category === category);
}
</code></pre> <p>Add <code>generateStaticParams</code> returning all three IDs and run <code>npm run build</code>: you'll see <code>/products/[id]</code> with <code>●</code> entries for <code>/products/1</code>, <code>/products/2</code> and <code>/products/3</code>. Now visit <code>/products/abc</code> on <code>next start</code>: the integer check calls <code>notFound()</code>.</p>

app/dashboard/loading.tsx<pre><code>export default function Loading() {
  return (
    &lt;div aria-busy="true" aria-live="polite"&gt;
      &lt;p&gt;Loading dashboard…&lt;/p&gt;
      &lt;div className="skeleton" style={{ height: 120 }} /&gt;
    &lt;/div&gt;
  );
}
</code></pre> <p>While <code>app/dashboard/page.tsx</code> is awaiting its data, this component is shown in its place. The layouts above it are already on screen and interactive. Two effects:</p> <ul> <li>Navigation feels instant. When you click a <code>&lt;Link&gt;</code> to <code>/dashboard</code>, the loading   UI is part of what was prefetched, so it appears immediately.</li> <li>The server can stream. The HTML up to the loading state is sent at once; the   page's content follows in the same response when ready.</li> </ul> <p>Prefer skeletons shaped like the real content over a spinner — they reduce layout shift when the content arrives. For finer-grained control (several independently loading sections in one page), use <code>&lt;Suspense&gt;</code> directly; Level 3 · 02 covers that.</p>

app/dashboard/error.tsx<pre><code>"use client"; // error boundaries must be Client Components

import { useEffect } from "react";

export default function DashboardError({
  error,
  retry,
}: {
  error: Error &amp; { digest?: string };
  retry: () =&gt; void;
}) {
  useEffect(() =&gt; {
    // report to your error tracker here
    console.error(error);
  }, [error]);

  return (
    &lt;div role="alert"&gt;
      &lt;h2&gt;We couldn’t load your dashboard.&lt;/h2&gt;
      &lt;p&gt;Reference: {error.digest ?? "n/a"}&lt;/p&gt;
      &lt;button onClick={() =&gt; retry()}&gt;Try again&lt;/button&gt;
    &lt;/div&gt;
  );
}
</code></pre> <p>If anything in the segment throws while rendering — a failed fetch, a bug — this component replaces the page, while the layout and the rest of the app keep working.</p> <ul> <li><code>retry()</code> re-fetches and re-renders the segment. It became a stable prop in Next.js   16.3 (added as <code>unstable_retry</code> in 16.2). On earlier versions use <code>reset()</code>, which   re-renders without re-fetching server data — so for a server-side failure you'd   combine it with <code>router.refresh()</code>.</li> <li>In production, error messages from Server Components are replaced with a generic   message so internals don't leak to users; <code>error.digest</code> is a hash you can match   against server logs, where the full error is printed.</li> </ul>

app/products/[id]/not-found.tsx<pre><code>import Link from "next/link";

export default function ProductNotFound() {
  return (
    &lt;main&gt;
      &lt;h1&gt;Product not found&lt;/h1&gt;
      &lt;p&gt;It may have been discontinued. &lt;Link href="/products"&gt;Browse all products&lt;/Link&gt;.&lt;/p&gt;
    &lt;/main&gt;
  );
}
</code></pre> <p>Call <code>notFound()</code> from <code>next/navigation</code> in a page, layout, <code>generateMetadata</code> or Server Action, and the nearest <code>not-found.tsx</code> renders. Like <code>redirect()</code>, it throws internally, so code after it doesn't run (and TypeScript knows the value can't be <code>null</code> afterwards).</p> <p><code>app/not-found.tsx</code> at the root also handles URLs that match no route at all.</p>

app/newsletter/page.tsx<pre><code>import { redirect } from "next/navigation";
import { addSubscriber } from "@/lib/subscribers";

export default function NewsletterPage() {
  async function subscribe(formData: FormData) {
    "use server";
    const email = String(formData.get("email") ?? "");
    await addSubscriber(email);
    redirect("/newsletter/thanks");
  }

  return (
    &lt;form action={subscribe}&gt;
      &lt;label htmlFor="email"&gt;Email&lt;/label&gt;
      &lt;input id="email" name="email" type="email" required /&gt;
      &lt;button&gt;Subscribe&lt;/button&gt;
    &lt;/form&gt;
  );
}
</code></pre> <p>The <code>"use server"</code> directive at the top of the function body marks it as a Server Action. Passed to <code>&lt;form action&gt;</code>, it receives the form's <code>FormData</code>. This form works even before JavaScript loads — it posts like an ordinary HTML form — and once React has hydrated, submissions happen without a full page reload.</p> <p>For anything beyond a demo, put actions in their own file with <code>"use server"</code> at the top; every exported async function in that file becomes an action, and Client Components can import them:</p> app/notes/actions.ts<pre><code>"use server";

import { revalidatePath } from "next/cache";

export type State = { error?: string; ok?: boolean };

const notes: string[] = []; // stand-in for a database

export async function listNotes() {
  return [...notes];
}

export async function addNote(prev: State, formData: FormData): Promise&lt;State&gt; {
  const text = String(formData.get("text") ?? "").trim();
  if (text.length &lt; 3) return { error: "Note must be at least 3 characters." };
  notes.push(text);
  revalidatePath("/notes");
  return { ok: true };
}
</code></pre>

next.config.ts<pre><code>import type { NextConfig } from "next";

const nextConfig: NextConfig = { cacheComponents: true };

export default nextConfig;
</code></pre> <p>Now caching is explicit and granular:</p> <ul> <li>Nothing async is cached by default.</li> <li><code>"use cache"</code> at the top of an async function or component caches its result. Its   arguments (and captured variables) form the cache key.</li> <li><code>cacheLife("hours")</code> (or <code>"minutes"</code>, <code>"days"</code>, <code>"max"</code>, a custom profile…) sets its   lifetime. <code>cacheTag("products")</code> labels it for invalidation.</li> <li>Anything uncached or request-dependent must be inside a <code>&lt;Suspense&gt;</code> boundary, so the   rest of the page can be prerendered as a static shell (this is Partial   Prerendering, which Cache Components turns on).</li> </ul> <p>Here is a page we built and compiled on Next.js 16.3.6:</p> lib/catalog.ts<pre><code>import { cacheLife, cacheTag } from "next/cache";

export async function getProducts() {
  "use cache";
  cacheLife("hours");
  cacheTag("products");
  return [
    { id: 1, name: "Mug", price: 12 },
    { id: 2, name: "Shirt", price: 25 },
  ]; // imagine a database query here
}
</code></pre> app/page.tsx<pre><code>import { Suspense } from "react";
import { cookies } from "next/headers";
import { getProducts } from "@/lib/catalog";

async function Greeting() {
  const name = (await cookies()).get("name")?.value ?? "guest";
  return &lt;p&gt;Welcome back, {name}&lt;/p&gt;;
}

export default async function Home() {
  const products = await getProducts();
  return (
    &lt;main&gt;
      &lt;h1&gt;Shop&lt;/h1&gt;
      &lt;Suspense fallback={&lt;p&gt;…&lt;/p&gt;}&gt;
        &lt;Greeting /&gt;
      &lt;/Suspense&gt;
      &lt;ul&gt;{products.map((p) =&gt; &lt;li key={p.id}&gt;{p.name}&lt;/li&gt;)}&lt;/ul&gt;
    &lt;/main&gt;
  );
}
</code></pre> <p>The build's route table:</p> <pre><code>Route (app)      Revalidate  Expire
┌ ◐ /                    1h      1d
├ ○ /_not-found
└ ○ /products

○  (Static)             prerendered as static content
◐  (Partial Prerender)  prerendered as static HTML with dynamic server-streamed content
</code></pre> <p><code>/</code> is <code>◐</code>: the heading and cached product list are in the static shell (revalidated per the <code>hours</code> profile), while the cookie-dependent greeting streams per request.</p> <p>We then removed the <code>&lt;Suspense&gt;</code> around <code>&lt;Greeting /&gt;</code> and rebuilt. The build failed, with a message listing three possible fixes: wrap the access in <code>&lt;Suspense&gt;</code>, cache it with <code>"use cache"</code>, or set <code>export const instant = false</code> to allow a blocking route. Cache Components turns "this page accidentally became dynamic" from a silent performance bug into a build error.</p>

app/api/posts/route.ts<pre><code>import { getPosts } from "@/lib/posts";

export async function GET() {
  return Response.json(await getPosts());
}

export async function POST(request: Request) {
  const body = await request.json();
  if (typeof body?.title !== "string") {
    return Response.json({ error: "title required" }, { status: 400 });
  }
  return Response.json({ ok: true, title: body.title }, { status: 201 });
}
